// Workflow B - Stage 1: split Django's sweep response into deliverable items.
// Django (B.0) is the messaging brain: every item already carries the app
// (channel), the exact words (message) and the claim marker (claim_ref) that
// keeps a reminder from ever going out twice. This node only reshapes the
// response; it writes no words and makes no choices.
const res = $input.first().json || {};

const items = [];
const collect = (list, kind) => {
  for (const raw of (Array.isArray(list) ? list : [])) {
    const channel = String((raw && raw.channel) || '').trim();
    const message = String((raw && raw.message) || '').trim();
    const claimRef = String((raw && raw.claim_ref) || '').trim();
    // A Django item without any of the three cannot be delivered responsibly:
    // no claim means a possible duplicate later, no words means nothing to send.
    if (!channel || !message || !claimRef) continue;
    items.push({ json: { ...raw, kind } });
  }
};

// Recovery first (the offer just died for those patients), then nudges.
collect(res.expired_offers, 'recovery');
collect(res.pre_expiry_nudges, 'nudge');

// An all-clear sweep returns zero items: the branch ends cleanly, no sends,
// no log writes. The 60-second silence IS the healthy state.
return items;

// Workflow B - Stage 2: turn each deliverable item into a provider request.
// Reads deployment config from $env - no node hardcodes a URL, key or token.
// Mock mode (PROVIDER_MOCK unset or true) points SMS/WhatsApp at the in-cluster
// Provider Simulator (06) so the real HTTP nodes, bodies and failure paths are
// exercised today. Telegram has no simulator leg, so it uses the real Bot API in
// both modes (a deliberate fake chat id exercises the failed-row path).
// Flip-live = PROVIDER_MOCK=false + real VOICEBIP_* / WHATSAPP_* / TELEGRAM_* values.
const env = (name, fallback = '') => {
  try { const v = $env[name]; return (v === undefined || v === null) ? fallback : String(v); }
  catch (e) { return fallback; }
};
const truthy = (v) => ['1', 'true', 'yes', 'on'].includes(String(v).trim().toLowerCase());

const providerMock = env('PROVIDER_MOCK') === '' ? true : truthy(env('PROVIDER_MOCK'));
const simulatorUrl = env('PROVIDER_SIMULATOR_URL', 'http://127.0.0.1:5678/webhook/provider-sim');

const cfg = {
  telegramToken: env('TELEGRAM_BOT_TOKEN'),
  voicebipApiUrl: env('VOICEBIP_API_URL'),
  voicebipApiKey: env('VOICEBIP_API_KEY'),
  smsSenderId: env('VOICEBIP_SMS_SENDER_ID', 'Cedarcare'),
  whatsappApiUrl: env('WHATSAPP_API_URL', 'https://graph.facebook.com/v19.0/'),
  whatsappPhoneId: env('WHATSAPP_PHONE_NUMBER_ID'),
  whatsappToken: env('WHATSAPP_ACCESS_TOKEN'),
};
// Meta rejects business-initiated free-form text outside the 24-hour customer
// service window (error 131047) - an expiry message is ALWAYS template mode.
// The approved template wraps Django's words as its single body parameter, so
// the clinic owns the wording even on WhatsApp. Mock mode uses a placeholder
// name so the simulator still exercises the template body.
const waTemplateName = providerMock
  ? env('WHATSAPP_TEMPLATE_NAME', 'mock_clinic_expiry_notice')
  : env('WHATSAPP_TEMPLATE_NAME');
const waTemplateLang = env('WHATSAPP_TEMPLATE_LANG', 'en_US') || 'en_US';

const liveConfigured = {
  telegram: Boolean(cfg.telegramToken),
  sms: Boolean(cfg.voicebipApiUrl && cfg.voicebipApiKey),
  whatsapp: Boolean(cfg.whatsappPhoneId && cfg.whatsappToken),
};
// Mock mode never skips for credentials: the simulator stands in for every
// configured provider (Telegram has no simulator, so it still needs a token).
const configured = providerMock
  ? { telegram: Boolean(cfg.telegramToken), sms: true, whatsapp: true }
  : liveConfigured;

const digitsOnly = (phone) => String(phone || '').replace(new RegExp('[^0-9]', 'g'), '');

const buildRequest = (item) => {
  const channel = item.channel;
  const to = digitsOnly(item.patient_phone);
  if (channel === 'telegram') {
    return {
      url: 'https://api.telegram.org/bot' + cfg.telegramToken + '/sendMessage',
      headers: {},
      body: {
        chat_id: item.telegram_chat_id,
        text: item.message,
        parse_mode: 'HTML',
        ...(item.reply_markup ? { reply_markup: item.reply_markup } : {}),
      },
    };
  }
  if (channel === 'sms') {
    return {
      url: providerMock ? simulatorUrl + '/sms' : cfg.voicebipApiUrl + '/sms',
      headers: { Authorization: providerMock ? 'Bearer mock' : 'Bearer ' + cfg.voicebipApiKey },
      body: { to, message: item.message, sender_id: cfg.smsSenderId,
        metadata: { request_code: item.request_id, channel: 'sms' } },
    };
  }
  // whatsapp: template body in both modes; the words ride as the body parameter.
  return {
    url: providerMock ? simulatorUrl + '/whatsapp' : cfg.whatsappApiUrl + cfg.whatsappPhoneId + '/messages',
    headers: { Authorization: providerMock ? 'Bearer mock' : 'Bearer ' + cfg.whatsappToken },
    body: {
      messaging_product: 'whatsapp',
      to,
      type: 'template',
      template: {
        name: waTemplateName,
        language: { code: waTemplateLang },
        components: [{ type: 'body', parameters: [{ type: 'text', text: String(item.message || '') }] }],
      },
      // Meta echoes this in every status callback, which links a real wamid
      // back to the BookingRequest (nothing else survives the round trip).
      biz_opaque_callback_data: item.request_id,
    },
  };
};

const out = [];
for (const wrapped of $input.all()) {
  const src = wrapped.json || {};
  const channel = String(src.channel || '').trim();
  const provider = channel === 'sms' ? 'voicebip'
    : (channel === 'whatsapp' ? 'meta_whatsapp' : 'telegram');
  const context = {
    claim_ref: src.claim_ref || '',
    request_id: src.request_id || '',
    patient_name: src.patient_name || '',
    patient_phone: src.patient_phone || '',
    service_name: src.service_name || '',
    channel,
    provider,
    kind: src.kind || '',
  };

  // Why a leg will not fire, most fundamental first. A skipped leg still
  // carries its context so the skip log can upsert the claim row visibly.
  let skipReason = null;
  if (channel === 'telegram' && !src.telegram_chat_id) skipReason = 'missing_chat_id';
  else if (!configured[channel]) skipReason = 'provider_not_configured';
  else if ((channel === 'sms' || channel === 'whatsapp') && !context.patient_phone) skipReason = 'missing_phone';
  else if (channel === 'whatsapp' && !waTemplateName) skipReason = 'whatsapp_template_not_configured';

  // Never build a request for a channel that will not send: a skipped leg has
  // no URL, and nothing downstream can accidentally use one.
  const request = skipReason ? { url: '', headers: {}, body: null } : buildRequest({ ...src, channel });
  out.push({ json: {
    provider_channel: channel,
    provider_request: {
      route: skipReason ? 'skip' : channel,
      skip_reason: skipReason,
      method: 'POST',
      ...request,
    },
    context,
    adapter_meta: { channel, provider, provider_mock: providerMock, request_id: context.request_id },
  } });
}
return out;

// Workflow B - skip visibility: a leg Django queued that n8n could not fire
// (no provider credentials in live mode, no approved WhatsApp template, no
// Telegram chat id) must be visible to reception, not vanish. Runs ONCE for
// every skipped leg in the run (n8n Code node default mode); each leg carries
// its own context. The claim row Django wrote is upserted to 'failed' with the
// reason, so the Needs Attention tab shows exactly which message was held back
// and why. Best-effort by design.
const out = [];
for (const wrapped of $input.all()) {
  const incoming = (wrapped && wrapped.json) || {};
  const context = incoming.context || {};

  if (!context.claim_ref) {
    out.push({ json: { context, interaction_log: { ok: false, error: 'skipped leg carried no claim ref; nothing posted' } } });
    continue;
  }

  const payload = {
    provider: context.provider || 'system',
    channel: context.channel || 'sms',
    direction: 'outbound',
    status: 'failed',
    patient_name: context.patient_name || '',
    patient_phone: context.patient_phone || '',
    request_code: context.request_id || '',
    external_ref: context.claim_ref || '',
    summary: 'Not sent (' + String(incoming.skip_reason || 'unknown') + '): queued for this channel, but the leg could not fire.',
    error_detail: 'Skip reason: ' + String(incoming.skip_reason || 'unknown'),
  };

  let logged = { ok: false };
  try {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: $env.DJANGO_API_BASE_URL + '/interactions/',
      headers: { 'Content-Type': 'application/json', 'X-Webhook-Secret': $env.DJANGO_WEBHOOK_SECRET || '' },
      body: payload,
      json: true,
    });
    logged = { ok: true, id: res.id, status: res.status };
  } catch (e) {
    logged = { ok: false, error: (e.message || String(e)).slice(0, 300) };
  }

  out.push({ json: { context, interaction_log: { ...logged, payload } } });
}

return out;

// Workflow B - Stage 3: record the delivery outcome on the claim row Django
// created. Runs ONCE for all of this channel's send responses in the run
// (n8n Code node default mode) - a run can carry several messages for the
// same app, e.g. two patients' SMS nudges. The switch preserves order, so
// response i is zipped to the i-th adapter item of this channel BY POSITION.
